namespace Northfield.Fiscal.Desktop.Resources;

internal static class CompanyActionIcons
{
    private const int IconSize = 28;

    public static Image Novo() => Extract(0);
    public static Image Editar() => Extract(1);
    public static Image Excluir() => Extract(2);
    public static Image Selecionar() => Extract(3);
    public static Image Duplicar() => Extract(4);
    public static Image AtivarInativar() => Extract(5);
    public static Image Historico() => Extract(6);
    public static Image Certificado() => Extract(7);
    public static Image Importar() => Extract(8);
    public static Image Exportar() => Extract(9);

    private static Bitmap DecodeSprite()
    {
        using var stream = new MemoryStream(Convert.FromBase64String(SpritePng));
        using var image = Image.FromStream(stream);
        return new Bitmap(image);
    }

    private static Image Extract(int index)
    {
        using var sprite = DecodeSprite();
        var rect = new Rectangle(index * IconSize, 0, IconSize, IconSize);
        return sprite.Clone(rect, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
    }

    private const string SpritePng = "...";
}
